# Load demos and build a transform function that works
with open(json_file) as f:
    demos = json.load(f)

def build_transform():
    """Read saved demos and build transform function"""
    import json

    def detect_structure_rows(grid):
        """Rows where ALL non-zero values are the same"""
        result = []
        for r in range(len(grid)):
            non_zero = [v for v in grid[r] if v != 0]
            if len(non_zero) > 0:
                if len(set(non_zero)) == 1:
                    result.append([r, non_zero[0]])
        return result

    def detect_content_cols(grid):
        """Columns where non-structure rows have consistent value, and multiple different values appear"""
        result = []
        # First identify structure rows
        struct_rows = detect_structure_rows(grid)
        struct_row_indices = set(r[0] for r in struct_rows)

        # For each column, check non-structure rows
        for c in range(len(grid[0])):
            col_vals_non_struct = []
            for r in range(len(grid)):
                if r not in struct_row_indices:
                    col_vals_non_struct.append(grid[r][c])

            # If non-structure values are all the same, and there's variance including that value
            if len(col_vals_non_struct) >= 1:
                check_vals = set(col_vals_non_struct)
                # Column is content if it has at least 2 different values
                # and those different values appear in the whole column across non-structure rows
                if len(check_vals) >= 2:
                    # Get the most common value among non-structure rows
                    from collections import Counter
                    counts = Counter(col_vals_non_struct)
                    most_common = max(counts.keys(), key=lambda k: counts[k])
                    # Include if there are at least 2 different values
                    result.append([c grid[c]: len(grid)], most_common, "main"
                # check the rest for my rule:
                # - Any cell in a content column gets the content value
                # - A cell only gets structure value if it IS in a structure row AND NOT in a content column
                #- Everything else is 0

output = np.zeros((7, 9), dtype=int)
H = [6, 1, 8]  # Structure values from rows 3,6,9
V = [3, 2, 7, 4]  # Content values from cols 2,5,7,10

for r in range(7):
    for c in range(9):
        is_struct_row = r in [1, 3, 5]
        is_content_col = c in [1, 3, 5, 7]

        if is_struct_row and is_content_col:
